DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_1','Unrung Bell[NEWLINE]Peaceful accumulation followed by a limited territorial response[NEWLINE]Culture or Science[NEWLINE][NEWLINE]Build Quietude during genuine peace, develop Belfry cities, and use the Great Toll to survive the first part of a war. The economy and combat reserve are different phases: war consumes the peaceful yields instead of leaving both active.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_2','Develop food, defense and cities that will make per-city Quietude useful. Avoid an unnecessary major or City-State war while building the peaceful counter. Barbarians do not break it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_3','Build Belfries in productive cities and protect the peace long enough to earn the desired stacks. Keep a standing army: a full counter does not make ordinary defenders invulnerable.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_4','When war begins, defend purposefully during the Toll and plan for its expiry. Further declarations in the same continuous war do not refill it. Make complete peace when rebuilding Quietude fits the strategic situation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_5','- Peaceful stacks add Culture across the empire and Science in Belfry cities.[NEWLINE]- Bellwarden territorial support can survive normal upgrades.[NEWLINE]- A prepared Toll can buy time at the start of a dangerous conflict.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_6','- A qualifying war removes the peaceful economic stacks.[NEWLINE]- The Toll has a finite window and cannot be renewed by adding another war.[NEWLINE]- Repeated or continuous hostility prevents a fresh peaceful reserve.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_7','- Avoid your main assault during the strongest initial Toll if time is on your side.[NEWLINE]- Keep meaningful pressure after the temporary response expires.[NEWLINE]- Use sustained economic or territorial threats rather than donating easy fights to a prepared defensive line.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_8','- Assuming Quietude remains active alongside wartime Toll bonuses.[NEWLINE]- Declaring extra wars to refresh the same Toll.[NEWLINE]- Confusing native friendly-land combat with an exclusively defensive or exactly owned-target-only rule.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A prepared territorial reserve can help stall a short Strength II offensive until its attacking window ends.[NEWLINE][NEWLINE]Beyond the Sky: Pikeman-derived units and a prepared friendly-land line can make an unsupported mounted rush expensive.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Sol Intellect: A protected specialist and construction economy can put pressure on a passive research race.[NEWLINE][NEWLINE]Viltrum: An extended conquest campaign can continue after the Toll expires and prevent Quietude from rebuilding.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_HEADING_10','Implementation and timing limits');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_CIV_TEXT_10','The implementation uses CP''s native friendly-land modifier, including its attack/defense and territorial interpretation; the more exclusive original design condition is not claimed.');
