INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_LEADER_BACKGROUND','Build Quietude during genuine peace, develop Belfry cities, and use the Great Toll to survive the first part of a war. The economy and combat reserve are different phases: war consumes the peaceful yields instead of leaving both active.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) SELECT 'TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_LEADER_BACKGROUND',Text FROM Language_en_US WHERE Tag='TXT_KEY_UNRUNG_LEADER_PEDIA';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_STRATEGY','Build Quietude during genuine peace, develop Belfry cities, and use the Great Toll to survive the first part of a war. The economy and combat reserve are different phases: war consumes the peaceful yields instead of leaving both active.[NEWLINE][NEWLINE]Develop food, defense and cities that will make per-city Quietude useful. Avoid an unnecessary major or City-State war while building the peaceful counter. Barbarians do not break it.[NEWLINE][NEWLINE]Build Belfries in productive cities and protect the peace long enough to earn the desired stacks. Keep a standing army: a full counter does not make ordinary defenders invulnerable.[NEWLINE][NEWLINE]When war begins, defend purposefully during the Toll and plan for its expiry. Further declarations in the same continuous war do not refill it. Make complete peace when rebuilding Quietude fits the strategic situation.');
