INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_LEADER_TEXT_1','Unrung Bell[NEWLINE]Peaceful accumulation followed by a limited territorial response[NEWLINE]Culture or Science[NEWLINE][NEWLINE]Build Quietude during genuine peace, develop Belfry cities, and use the Great Toll to survive the first part of a war. The economy and combat reserve are different phases: war consumes the peaceful yields instead of leaving both active.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_LEADER_TEXT_2','Develop food, defense and cities that will make per-city Quietude useful. Avoid an unnecessary major or City-State war while building the peaceful counter. Barbarians do not break it.[NEWLINE][NEWLINE]Build Belfries in productive cities and protect the peace long enough to earn the desired stacks. Keep a standing army: a full counter does not make ordinary defenders invulnerable.[NEWLINE][NEWLINE]When war begins, defend purposefully during the Toll and plan for its expiry. Further declarations in the same continuous war do not refill it. Make complete peace when rebuilding Quietude fits the strategic situation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFTHEUNRUNGBELL_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]The Urgal: A prepared territorial reserve can help stall a short Strength II offensive until its attacking window ends.[NEWLINE][NEWLINE]Beyond the Sky: Pikeman-derived units and a prepared friendly-land line can make an unsupported mounted rush expensive.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]Sol Intellect: A protected specialist and construction economy can put pressure on a passive research race.[NEWLINE][NEWLINE]Viltrum: An extended conquest campaign can continue after the Toll expires and prevent Quietude from rebuilding.');
